    .expect(200);
  const resp = await request(app).post(`/inscricoes/${espera.body.id}/confirmacao`).set('X-Usuario', 'p-joao');
  expect(resp.status).toBe(422);
  expect(resp.body.erro).toBe('CONVOCACAO_EXPIRADA');
});

